<?php require_once 'includes/config.php'; require_teacher(); $tid=current_teacher_id();
$q=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,c.id AS ClassId,c.ClassName,c.Section FROM teacher_student_assignments a JOIN tblstudents s ON s.StudentId=a.student_id JOIN tblclasses c ON c.id=a.class_id JOIN teacher_class_assignments ca ON ca.teacher_id=a.teacher_id AND ca.class_id=a.class_id WHERE a.teacher_id=:t ORDER BY c.ClassNameNumeric,c.Section,s.StudentName');$q->execute([':t'=>$tid]);$rows=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Students | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><nav class="navbar navbar-default srms-mobile-nav"><div class="container-fluid"><a class="navbar-brand" href="teacher-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text pull-right"><img src="profile-photo.php?type=teacher&id=<?php echo (int)($_SESSION['teacher_id']??0);?>" alt="Profile photo" width="28" height="28" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'"> <?php echo e($_SESSION['teacher_name']??'Teacher');?> · <a href="teacher-logout.php">Sign out</a></p></div></nav><div class="container-fluid srms-page"><div class="srms-toolbar"><a class="btn btn-default" href="teacher-dashboard.php">← Dashboard</a><a class="btn btn-danger pull-right" href="teacher-logout.php">Logout</a></div><h2>My Assigned Students</h2><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>#</th><th>Student</th><th>Roll ID</th><th>Class</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?php echo $i+1;?></td><td><?php echo e($r['StudentName']);?></td><td><?php echo e($r['RollId']);?></td><td><?php echo e($r['ClassName'].' ('.$r['Section'].')');?></td><td><a class="btn btn-primary btn-xs" href="teacher-grade.php?student_id=<?php echo (int)$r['StudentId'];?>&class_id=<?php echo (int)$r['ClassId']??0;?>">Grade</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
